before.content:
[role="tablist"] { display: flex; flex-wrap: wrap; gap: .35rem; }
[role="tab"] { padding: .5rem .7rem; border: 0; border-radius: .5rem; background: #e8ebf1; }
[role="tab"][data-state="active"] { color: white; background: #315fd6; }
.settings-section { max-width: 48rem; }
.profile-list { display: grid; gap: 1rem; }
.profile-editor { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; padding: 1.2rem; border-radius: .9rem; background: white; box-shadow: 0 10px 34px rgba(32,43,67,.05); }

after.content:
  .queue { max-height: 8rem; overflow: auto; }
  .page { min-height: calc(100vh - 3.5rem); }
  .profile-editor { grid-template-columns: minmax(0, 1fr); }
  .profile-editor > header, .profile-actions, .profile-editor > .warning, .profile-editor > .error, .profile-collection { grid-column: auto; }
  .model-editor, .header-editor { grid-template-columns: minmax(0, 1fr); }
}
@media (prefers-color-scheme: dark) {
  :root { color: #e7ecf5; background: #0b1220; }
